const roles = {
explorer:['Keşif','Exploration','Dosyaları ve mevcut yapıyı okuyarak işin yerini bulur.','Reads files and the existing structure to locate the work.'],
fast_lookup:['Hızlı arama','Quick lookup','Dar bir sorunun yanıtını dosya veya kayıtlarda bulur.','Finds the answer to a narrow question in files or records.'],
researcher:['Araştırma','Research','Güncel kaynakları inceler ve bulgularını açıklar.','Checks current sources and explains the findings.'],
implementer:['Uygulama','Implementation','Kendisine verilen sınırlar içinde değişikliği yapar.','Makes the change within its assigned scope.'],
verifier:['Kontrol','Verification','Hazır değişikliği test eder ve sonucu bildirir.','Tests the completed change and reports the result.'],
reviewer:['Gözden geçirme','Review','Değişikliği bağımsız olarak okuyup sorunları bildirir.','Independently reads the change and reports issues.'],
failure_analyst:['Sorun çözme','Failure analysis','Somut bir hatanın nedenini araştırır.','Investigates the cause of a concrete failure.'],
qa_operator:['Ekran kontrolü','Screen testing','Gerçek ekranı kullanarak akışları ve görünümü kontrol eder.','Uses the real screen to check flows and appearance.'],
advisor:['Danışman','Advisor','Önemli bir kararın risklerini değerlendirir.','Assesses the risks of an important decision.']
};
const providerNames = {codex:'Codex',claude:'Claude Code',opencode:'OpenCode'};
const installationReceipts=new Map();
const state = {csrf:'',revision:0,projects:[],orchestras:[],selected_projects:[],selected_providers:[],roots:[],defaults:{},project_overrides:{},providers:[],catalogs:{},jobs:[],page:'projects',busy:false,onboard:false,onboardStep:1,usage:null};
const clone = value => JSON.parse(JSON.stringify(value));
const t = (key, values={}) => (words[lang][key] || key).replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??''));
const roleLabel = role => roles[role]?.[lang==='tr'?0:1] || role;
const roleDescription = role => roles[role]?.[lang==='tr'?2:3] || t('roleUnknown');
const node = (tag, className='', content) => {const element=document.createElement(tag);if(className)element.className=className;if(content!==undefined)element.textContent=String(content);return element;};
const button = (label, action, kind='', disabled=false) => {const b=node('button','button '+kind,label);b.type='button';b.disabled=disabled;b.addEventListener('click',action);return b;};
const field = (label,input,wide=false) => {const holder=node('label','field'+(wide?' wide':''));const caption=node('span','',label);caption.id='field-'+crypto.randomUUID();input.setAttribute('aria-labelledby',caption.id);holder.append(caption,input);return holder;};
const input = (value='',type='text') => {const el=node('input');el.type=type;el.value=value;return el;};
const select = (entries,value='') => {const el=node('select');for(const entry of entries)el.append(new Option(entry[1],entry[0]));el.value=value;return el;};
const badge = (text,kind='') => node('span','badge '+kind,text);
const errorText = error => typeof error==='string'?error:error?.message||JSON.stringify(error||{});
const projectById = id => state.projects.find(p=>p.id===id);
const orchestraById = id => state.orchestras.find(o=>o.id===id);
const providers = () => state.providers.map(p=>typeof p==='string'?{id:p}:p).filter(p=>providerNames[p.id||p.provider]).map(p=>({...p,id:p.id||p.provider}));
const selectedProviders = () => state.selected_providers.filter(p=>providerNames[p]);
function notify(key,kind='',values={}) {const el=$('notice');el.replaceChildren(node('span','',t(key,values)));el.className='notice '+kind;el.hidden=false;const status=$('modal-status');if(status){status.hidden=false;status.className='notice '+kind;status.textContent=t(key,values);}const inline=$('choice-status');if(inline){inline.hidden=false;inline.className='notice inline-status '+kind;inline.textContent=t(key,values);}}
function friendlyError(error){const message=errorText(error);const exact={'A directory path is required':'folderRequired','Project path must be a directory':'folderDirectory','Project folder is unavailable; refresh the registry':'folderUnavailable','Project path changed; refresh registry':'folderChanged','Preview expired or metadata changed; preview again':'stale','Unknown or already consumed preview':'stale','Fresh preview required':'stale','Files changed since preview; preview again':'conflict','Native folder picker is unavailable; enter a folder path manually':'pickerUnavailable','Folder picker is unavailable or timed out; enter a folder path manually':'pickerUnavailable','Folder picker could not open; enter a folder path manually':'pickerUnavailable','OpenCode backend does not expose safe roster restore':'restoreUnsupported'};if(error?.code==='csrf')return 'stale';if(exact[message])return exact[message];if(/^\[Errno 2\] No such file or directory(?::|$)/.test(message)||/^\[WinError (2|3)\]/.test(message))return 'folderMissing';if(/^\[Errno 13\] Permission denied(?::|$)/.test(message)||/^\[WinError 5\]/.test(message))return 'folderAccess';if(error?.context==='project-add')return 'folderAddFailed';if(['Managed file conflict: ','Files changed since preview; preview again: ','Team file changed since preview: ','File changed during Save: ','File changed after Save; restore refused: ','File changed during Restore: '].some(prefix=>message.startsWith(prefix)))return 'conflict';return 'error';}
function showError(error) {const message=errorText(error);notify(friendlyError(error),'error');const details=node('details');details.append(node('summary','',t('errorDetails')),node('p','',message));for(const target of [$('notice'),$('modal-status'),$('choice-status')].filter(Boolean)){if(error?.path)target.append(node('p','path',error.path));target.append(details.cloneNode(true));}}

async function perform(key,action,success) {if(state.busy)return;state.busy=true;notify(key,'busy');document.querySelectorAll('.button,input,select,textarea').forEach(b=>{b.dataset.wasDisabled=String(b.disabled);b.disabled=true;});try {const result=await action();notify(success||'done','success');return result;}catch(error){showError(error);return null;}finally{state.busy=false;document.querySelectorAll('[data-was-disabled]').forEach(b=>{b.disabled=b.dataset.wasDisabled==='true';delete b.dataset.wasDisabled;});}}
export const api = {
async request(path,body) {
 if(demo)return demoRequest(path,body);
 if(body!==undefined&&!state.csrf)throw Error(t('loadError'));
 const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{'Accept':'application/json'}:{'Content-Type':'application/json','Accept':'application/json','X-Ustam-CSRF':state.csrf},...(body===undefined?{}:{body:JSON.stringify(body)})});
 let data;try{data=await response.json();}catch{throw Error(t('loadError'));}
 if(!response.ok||data.ok===false){const error=Error(errorText(data.error)||t('error'));error.code=data.error?.code;error.partial=data.results;throw error;}return data;
},bootstrap(){return this.request('/api/bootstrap');},projects(body){return this.request('/api/projects',body);},orchestras(body){return this.request('/api/orchestras',body);},defaults(body){return this.request('/api/defaults',body);},models(provider,project){return this.request('/api/models?'+new URLSearchParams({provider,...(project?{project_id:project}:{})}));},preview(body){return this.request('/api/preview',body);},apply(ids){return this.request('/api/apply',{preview_ids:ids});},restore(body){return this.request('/api/restore',body);},usage(project,provider){return this.request('/api/usage?'+new URLSearchParams({project_id:project,provider}));},jobs(body){return this.request('/api/jobs',body);},job(id){return this.request('/api/jobs/'+encodeURIComponent(id));}
};
function merge(data) {for(const key of ['csrf','revision','projects','orchestras','selected_projects','selected_providers','roots','defaults','project_overrides','providers','capabilities','provider_status'])if(data[key]!==undefined)state[key]=data[key];validateInstallationReceipts();}
async function bootstrap(){const data=await api.bootstrap();merge(data);return data;}
async function metadata(action,success) {return perform('busy',async()=>{const response=await action();merge(response);if(response.revision===undefined)await bootstrap();render();return response;},success);}
function modal(title,content,actions=[]) {$('modal-content').replaceChildren();const head=node('div','modal-head');const titleNode=node('h2','',title);titleNode.tabIndex=-1;head.append(titleNode,button('×',()=> $('modal').close(),'modal-close'));const status=node('div','notice');status.id='modal-status';status.hidden=true;status.setAttribute('role','status');status.setAttribute('aria-live','polite');$('modal-content').append(head,status,content);if(actions.length){const footer=node('div','modal-actions');footer.append(...actions);$('modal-content').append(footer);}if(!$('modal').open)$('modal').showModal();titleNode.focus({preventScroll:true});}
function heading(title,hint,actions=[]) {const head=node('div','page-heading');const text=node('div');text.append(node('div','eyebrow',t('heroEye')),node('h1','',title),node('p','wide-text',hint));const controls=node('div','actions');controls.append(...actions);head.append(text,controls);return head;}
function providerSelect(value){return select(selectedProviders().map(id=>[id,providerNames[id]]),value||selectedProviders()[0]);}
function orchestraSelect(provider,value,empty=true){return select([...(empty?[['',t('chooseOrchestra')]]:[]),...state.orchestras.filter(o=>o.provider===provider).map(o=>[o.id,o.name])],value||'');}
function assigned(project,provider){const override=state.project_overrides[project.id]||{};return override.orchestras?.[provider]||override.orchestra_id||state.defaults.orchestras?.[provider]||'';}
function providerStatus(provider){const status=state.provider_status?.[provider.id]||provider;const detected=status.detected??status.installed??status.available;if(detected===true)return ['detected','good'];if(detected===false)return ['unavailable','warning'];return ['available',''];}
function providerOptions(chosen){const list=node('div','provider-list');for(const p of providers()){const card=node('div','provider-option');const checkbox=input('','checkbox');checkbox.checked=chosen.has(p.id);checkbox.addEventListener('change',()=>checkbox.checked?chosen.add(p.id):chosen.delete(p.id));const label=node('label');label.append(checkbox,node('span','',providerNames[p.id]));const [key,kind]=providerStatus(p);card.append(label,node('p','',t(key)),badge(providerNames[p.id]+' '+t('capability'),kind));list.append(card);}return list;}
function renderStatic(){document.documentElement.lang=lang;$('language').value=lang;$('language-label').textContent=t('language');$('edition').textContent=selectedProviders().map(id=>providerNames[id]).join(' · ')||'Codex · Claude Code · OpenCode';$('nav-label').textContent=t('workspace');$('local-title').textContent=t('local');$('local-note').textContent=t('localNote');$('footer').textContent=t('footer');$('demo-label').textContent=t('demo');$('demo-label').hidden=!demo;$('nav').replaceChildren();for(const [id,icon] of [['projects','▦'],['orchestras','♬'],['usage','◴'],['settings','⚙']]){const b=node('button',(state.page===id)?'active':'');b.type='button';b.setAttribute('aria-current',(state.page===id)?'page':'false');const iconNode=node('span','nav-icon',icon);iconNode.setAttribute('aria-hidden','true');b.append(iconNode,node('span','',t(id)));b.addEventListener('click',()=>{state.page=id;render();});$('nav').append(b);}}
function renderOnboarding() {const holder=$('onboarding');holder.hidden=!state.onboard;holder.replaceChildren();if(!state.onboard)return;holder.className='onboarding';if(state.onboardStep===1){holder.append(node('div','steps',t('step')),node('h2','',t('welcome')),node('p','',t('welcomeHint')));const chosen=new Set(selectedProviders());holder.append(providerOptions(chosen),node('p','',t('providerNote')),button(t('ready'),async()=>{if(!chosen.size)return notify('chooseProvider','error');const result=await metadata(()=>api.defaults({selected_providers:[...chosen],revision:state.revision}),'saved');if(result){state.onboardStep=2;renderOnboarding();}},'primary'));}else{holder.append(node('h2','',t('readyTitle')),node('p','',t('toolsSelectedHint')),node('p','',t('readyHint')));const actions=node('div','actions');actions.append(button(t('addProject'),()=>addProjectDialog(true),'primary'),button(t('optionalRoots'),()=>rootDialog(true)),button(t('later'),()=>finishOnboarding()));holder.append(actions);}}
function finishOnboarding(){state.onboard=false;try{localStorage.setItem('ustam-onboarded','1');}catch{}renderOnboarding();}
function render(){renderStatic();renderOnboarding();if(state.page==='projects')renderProjects();if(state.page==='orchestras')renderOrchestras();if(state.page==='usage')renderUsage();if(state.page==='settings')renderSettings();}
async function selection(ids,project){const result=await metadata(()=>api.projects({action:'selection',ids,providers:selectedProviders(),revision:state.revision}),'saved');if(result&&project)showOrchestraChoice(project);}
