function createChoiceOrchestra(){const choice=state.orchestraChoice;if(!choice)return;const catalog=state.catalogs[choice.provider];const profile=catalog?.profiles.includes('balanced')?'balanced':catalog?.profiles[0];editChoiceOrchestra(startingDraft(choice.provider,profile)||blankOrchestra(choice.provider));}
function editChoiceOrchestra(draft){const choice=state.orchestraChoice;if(!choice)return;choice.customTouched=Boolean(choice.preview===draft&&choice.previewTouched)||Boolean(orchestraById(draft.id));choice.task_type=draft.task_type||choice.task_type||'feature';choice.branch='custom';choice.preview=null;choice.customDraft=clone(draft);choice.editing=true;renderOrchestraChoice();}

